import numpy as np
import matplotlib.pyplot as plt

# Метод Ньютона
def newton(f, df, x0, tol=1e-6, max_iter=100):
    x = x0
    iterations = []
    values = []
    for i in range(max_iter):
        try:
            x_next = x - f(x) / df(x)
        except ZeroDivisionError:
            return None, iterations, values  # Прерывание при делении на ноль
        iterations.append(i)
        values.append(x)
        if abs(x_next - x) < tol:
            return x_next, iterations, values
        x = x_next
    return None, iterations, values

# Градиентный спуск
def gradient_descent(f, df, x0, learning_rate=0.1, tol=1e-6, max_iter=100):
    x = x0
    iterations = []
    values = []
    for i in range(max_iter):
        x_next = x - learning_rate * df(x)
        iterations.append(i)
        values.append(x)
        if abs(x_next - x) < tol:
            return x_next, iterations, values
        x = x_next
    return None, iterations, values

# Функция и ее производная
def f(x):
    return x**4

def df(x):
    return 4*x**3

# Начальное приближение
x0 = 2

# Запуск методов
newton_result, newton_iterations, newton_values = newton(f, df, x0)
gradient_descent_result, gradient_descent_iterations, gradient_descent_values = gradient_descent(f, df, x0)

# Вывод результатов
if newton_result is not None:
    print(f"Метод Ньютона: корень = {newton_result:.4f}, итераций = {len(newton_iterations)}")
else:
