if gradient_descent_result is not None:
    print(f"Градиентный спуск: корень = {gradient_descent_result:.4f}, итераций = {len(gradient_descent_iterations)}")
else:
    print("Градиентный спуск: не сошелся")

# Построение графиков
plt.figure(figsize=(10, 6))
plt.plot(newton_iterations, newton_values, marker='o', label='Метод Ньютона')
plt.plot(gradient_descent_iterations, gradient_descent_values, marker='x', label='Градиентный спуск')
plt.xlabel('Итерация')
plt.ylabel('Значение x')
plt.title('Сходимость методов Ньютона и градиентного спуска')
plt.legend()
plt.grid(True)
plt.show()
"""
